package p4_test

import (
	"bytes"
	"encoding/binary"
	"encoding/hex"
	"github.com/masahitojp/mariamem/internal/generatedgo/code/base"
	"github.com/masahitojp/mariamem/internal/generatedgo/code/p4"
	_ "github.com/masahitojp/mariamem/internal/generatedgo/code/p8"
	"math/rand"
	"sync/atomic"
	"testing"
	"unsafe"
)

func crcModule() *base.Module {
	mem := make([]byte, 32<<20)
	m := &base.Module{Memory: mem, M: unsafe.Pointer(unsafe.SliceData(mem)), MemSize: &atomic.Uint64{}, G0: 1 << 20}
	m.MemSize.Store(uint64(len(mem)))
	table, e := hex.DecodeString("")
	if e != nil {
		panic(e)
	}
	copy(mem[16318144:], table)
	return m
}
func crcBitwise(b []byte) uint32 {
	c := ^uint32(0)
	for _, v := range b {
		c ^= uint32(v)
		for i := 0; i < 8; i++ {
			if c&1 != 0 {
				c = c>>1 ^ 0x82f63b78
			} else {
				c >>= 1
			}
		}
	}
	return ^c
}
func TestCRC32CEquivalence(t *testing.T) {
	m := crcModule()
	rng := rand.New(rand.NewSource(53))
	cases := 0
	for _, n := range []int{0, 1, 2, 3, 4, 7, 8, 9, 15, 16, 17, 31, 32, 33, 63, 64, 65, 255, 256, 257, 4092, 8192, 16380, 16384, 32764, 65532} {
		for off := 0; off < 32; off++ {
			a := (2 << 20) + off
			b := m.Memory[a : a+n]
			rng.Read(b)
			before := append([]byte(nil), b...)
			want := crcBitwise(b)
			fast := base.CRC32C(m, int32(a), int32(n))
			if fast != want || !bytes.Equal(before, b) {
				t.Fatalf("length=%d offset=%d fast=%x want=%x", n, off, fast, want)
			}
			cases++
		}
	}
	a := int32(2 << 20)
	copy(m.Memory[a:], []byte("123456789"))
	if base.CRC32C(m, a, 9) != 0xe3069283 {
		t.Fatal("known CRC32C vector")
	}
	t.Logf("%d lengths/alignment cases + independent bitwise + known vector PASS", cases)
	for _, pair := range [][2]int32{{-1, 1}, {1, -1}, {32 << 20, 1}, {(32 << 20) - 1, 2}} {
		caught := false
		func() { defer func() { caught = recover() != nil }(); base.CRC32C(m, pair[0], pair[1]) }()
		if !caught {
			t.Fatal("bounds accepted", pair)
		}
	}
	if base.CRC32C(m, 32<<20, 0) != 0 {
		t.Fatal("empty boundary")
	}
}
func TestCRC32CPageValidation(t *testing.T) {
	m := crcModule()
	rng := rand.New(rand.NewSource(117))
	cases := 0
	for _, size := range []int{4096, 8192, 16384, 32768, 65536} {
		binary.LittleEndian.PutUint32(m.Memory[27613680:], uint32(size))
		for _, off := range []int{0, 1, 7, 15} {
			addr := (2 << 20) + off
			page := m.Memory[addr : addr+size]
			rng.Read(page)
			clear(page[:4])
			clear(page[16:26])
			clear(page[size-8 : size-4])
			binary.BigEndian.PutUint32(page[size-4:], crcBitwise(page[:size-4]))
			pristine := append([]byte(nil), page...)
			for _, mutation := range []string{"valid", "payload", "checksum", "lsn"} {
				copy(page, pristine)
				switch mutation {
				case "payload":
					page[100] ^= 1
				case "checksum":
					page[size-1] ^= 1
				case "lsn":
					page[20] = 1
					binary.BigEndian.PutUint32(page[size-4:], crcBitwise(page[:size-4]))
				}
				before := append([]byte(nil), page...)
				old := originalCRCValidator(m, 0, int32(addr), 16)
				fast := p4.Fn18142(m, 0, int32(addr), 16)
				if old != fast || (mutation == "valid" && old != 0) || (mutation != "valid" && old == 0) || !bytes.Equal(before, page) || m.ExcPending != 0 {
					t.Fatalf("size=%d offset=%d mutation=%s old=%d fast=%d", size, off, mutation, old, fast)
				}
				cases++
			}
		}
	}
	t.Logf("%d actual Fn18142 valid/corrupt/LSN cases PASS", cases)
}
